  "Potline records — anode-effect minutes per cell-day (or overvoltage and current efficiency) for the month": "पॉटलाइन रिकॉर्ड — महीने के लिए प्रति सेल-दिन एनोड-प्रभाव मिनट (या ओवरवोल्टेज और करंट दक्षता)",
