  "Field-measurement report behind the installation's own CF₄ and C₂F₆ factors": "संयंत्र के अपने CF₄ और C₂F₆ गुणांकों के पीछे की क्षेत्र-मापन रिपोर्ट",
  "The consultant or laboratory that measured the duct — renewed at least every three years": "वह सलाहकार या प्रयोगशाला जिसने डक्ट मापी — कम से कम हर तीन साल में नवीनीकृत",
  "Scrap receiving records — tonnes by type and whether pre-consumer or post-consumer": "स्क्रैप प्राप्ति रिकॉर्ड — प्रकार के अनुसार टन, और प्री-कंज़्यूमर या पोस्ट-कंज़्यूमर",
