  "Count the anode effects one of two ways — minutes per cell per day (the slope method) or the overvoltage — and use the factors for the cell type until you have measured your own.": "एनोड-प्रभाव दो में से एक तरीक़े से गिनें — प्रति सेल प्रति दिन मिनट (ढलान विधि) या ओवरवोल्टेज — और अपने मापे गुणांक आने तक सेल प्रकार के गुणांक उपयोग करें।",
  "Counted as not emitted, so it comes off the month's emissions. Only what was actually stored or bound.": "उत्सर्जित नहीं गिना गया, इसलिए यह महीने के उत्सर्जन से घटता है। केवल वही जो वास्तव में संग्रहीत या बाँधा गया।",
  "Country": "देश",
  "Country code first, then letters, numbers and single hyphens — 5 to 32 characters. The country must match, because a mismatched prefix is nearly always a reference copied from another plant.": "पहले देश का कोड, फिर अक्षर, संख्याएँ और एकल हाइफ़न — 5 से 32 अक्षर। देश मेल खाना चाहिए, क्योंकि बेमेल उपसर्ग लगभग हमेशा किसी और संयंत्र से कॉपी किया संदर्भ होता है।",
