  "Declared in the draft methodology. It prints, but under a version nobody has stamped.": "मसौदा कार्यप्रणाली में घोषित। यह छपता है, पर ऐसे संस्करण के तहत जिस पर किसी ने मुहर नहीं लगाई।",
