  "Due today": "आज देय",
  "During an anode effect an electrolysis cell emits CF₄ and C₂F₆, gases that warm the atmosphere thousands of times more than CO₂. They are counted as CO₂ equivalent: CF₄ × 6,630 and C₂F₆ × 11,100.": "एनोड-प्रभाव के दौरान विद्युत-अपघटन सेल CF₄ और C₂F₆ उत्सर्जित करता है, वे गैसें जो वातावरण को CO₂ से हज़ारों गुना अधिक गर्म करती हैं। इन्हें CO₂ समतुल्य में गिना जाता है: CF₄ × 6,630 और C₂F₆ × 11,100।",
