  "Emissions read by a continuous emissions measurement system on a stack — added to the month's emissions.": "स्टैक पर निरंतर उत्सर्जन मापन प्रणाली द्वारा पढ़ा गया उत्सर्जन — महीने के उत्सर्जन में जोड़ा जाता है।",
