  "Entry": "प्रविष्टि",
  "Established by field measurement to industry best practice, within ±15%, and renewed at least every three years or when the cells change. Attach the measurement report on the Documents step.": "क्षेत्रीय मापन से उद्योग की सर्वोत्तम पद्धति के अनुसार स्थापित, ±15% के भीतर, और कम से कम हर तीन साल में या सेल बदलने पर नवीनीकृत। मापन रिपोर्ट दस्तावेज़ चरण में संलग्न करें।",
  "Every answer is saved to Certrace for the company that sent you this link — you can close this page and come back to it from any device.": "हर उत्तर उस कंपनी के लिए Certrace में सहेजा जाता है जिसने आपको यह लिंक भेजा — आप यह पन्ना बंद करके किसी भी उपकरण से दोबारा आ सकते हैं।",
  "Every answer stays in this browser until Certrace’s hosted service is connected.": "हर उत्तर इस ब्राउज़र में तब तक रहता है जब तक Certrace की होस्टेड सेवा जुड़ नहीं जाती।",
  "Every conversation you have with Cera is kept here, so you can pick it up again.": "Cera से आपकी हर बातचीत यहाँ रखी जाती है, ताकि आप उसे फिर से उठा सकें।",
  "Every fuel burned inside the boundary across the whole year, and the meter that measures each one.": "पूरे साल में सीमा के भीतर जला हर ईंधन, और हर एक को मापने वाला मीटर।",
  "Every fuel burned inside the boundary this month, with the quantity as your invoice states it.": "इस महीने सीमा के भीतर जला हर ईंधन, मात्रा वैसी जैसी आपके बिल में है।",
  "Every fuel used across the year, not only this month. Choosing one adds its row to the monthly readings.": "पूरे साल उपयोग हुआ हर ईंधन, केवल इस महीने का नहीं। एक चुनने से उसकी पंक्ति मासिक रीडिंग में जुड़ जाती है।",
  "Every process on the list is already declared outside the boundary. If that is right, nothing is inside it — check the “Processes included” list above.": "सूची की हर प्रक्रिया पहले से सीमा के बाहर घोषित है। अगर यह सही है, तो उसके भीतर कुछ नहीं है — ऊपर की “शामिल प्रक्रियाएँ” सूची जाँचें।",
  "Everything needed is in": "ज़रूरी सब कुछ आ गया",
  "Everything saves as you type, so you can leave and come back on this machine. Nothing is submitted until you sign on the last step.": "टाइप करते ही सब सहेजा जाता है, इसलिए आप इसी मशीन पर जाकर लौट सकते हैं। आख़िरी चरण पर हस्ताक्षर करने तक कुछ भी जमा नहीं होता।",
  "Everything the whole installation drew": "पूरे संयंत्र ने जो कुछ लिया",
  "Everything you dropped has been filed or set aside.": "जो कुछ आपने छोड़ा था वह दर्ज हो गया या अलग रख दिया गया।",
  "Example.": "उदाहरण।",
  "Exit full screen": "पूर्ण स्क्रीन से बाहर",
  "Factor source": "गुणांक का स्रोत",
  "Files stay in your browser for this demo — names and sizes are recorded so you can see the flow; nothing is uploaded to a server.": "इस डेमो में फ़ाइलें आपके ब्राउज़र में रहती हैं — नाम और आकार दर्ज होते हैं ताकि आप प्रवाह देख सकें; कुछ भी सर्वर पर अपलोड नहीं होता।",
  "Fill from the other product reports": "अन्य उत्पाद रिपोर्टों से भरें",
  "Filled by Cera from {file}. Cera can make mistakes — check it against the document and edit it if it is wrong.": "{file} से Cera ने भरा। Cera से ग़लती हो सकती है — इसे दस्तावेज़ से जाँचें और ग़लत हो तो सुधारें।",
  "Filled in": "भरा गया",
  "Finish the required fields first": "पहले आवश्यक फ़ील्ड पूरे करें",
  "First month of the year — nothing to copy from yet.": "साल का पहला महीना — अभी कॉपी करने को कुछ नहीं।",
  "Fix the figures marked in red to continue.": "आगे बढ़ने के लिए लाल निशान वाले आँकड़े ठीक करें।",
  "Fixed when the precursor was added": "प्रीकर्सर जोड़ते समय तय हुआ",
  "Flow": "प्रवाह",
  "Fluxes and chemicals": "फ़्लक्स और रसायन",
  "Fluxes and flue-gas chemicals": "फ़्लक्स और फ़्लू-गैस रसायन",
  "For the month, across every product it feeds.": "महीने के लिए, उन सभी उत्पादों में जिन्हें यह आपूर्ति करता है।",
  "For {exporter} — fill each section, attach documents, run the check, then sign and submit.": "{exporter} के लिए — हर अनुभाग भरें, दस्तावेज़ संलग्न करें, जाँच चलाएँ, फिर हस्ताक्षर करके जमा करें।",
  "Four things most plants have nothing to say about. Each one opens by itself when the installation's own answers say it applies here, and stays shut otherwise — so an empty block is a correct answer, not a gap.": "चार बातें जिनके बारे में अधिकांश संयंत्रों को कुछ कहना नहीं होता। जब संयंत्र के अपने उत्तर कहते हैं कि यह यहाँ लागू है तो हर एक अपने-आप खुलता है, वरना बंद रहता है — इसलिए ख़ाली खंड सही उत्तर है, अंतर नहीं।",
  "From": "से",
