  "Grouped by who usually holds each document — Operations, Finance, Suppliers, Lab, and Organisation-level — so nothing has to be chased from a list that mixes all five together.": "इस पर समूहित कि हर दस्तावेज़ आमतौर पर किसके पास होता है — संचालन, वित्त, आपूर्तिकर्ता, प्रयोगशाला, और संगठन-स्तर — ताकि पाँचों को मिलाकर बनी सूची से कुछ ढूँढ़ना न पड़े।",
  "Guessed from the file name — check what it is.": "फ़ाइल के नाम से अनुमान लगाया — जाँचें कि यह क्या है।",
