  "Heat that came in from, or went out to, another installation — and what was made and used on site.": "वह ऊष्मा जो किसी अन्य संयंत्र से आई या वहाँ गई — और जो साइट पर बनी और उपयोग हुई।",
  "Here is what AI found and where each value will go. Nothing is saved until you confirm.": "AI ने जो पाया और हर मान कहाँ जाएगा, वह यह है। आपके पुष्टि करने तक कुछ सहेजा नहीं जाता।",
