  "How to fill it.": "इसे कैसे भरें।",
  "How you make it — tells the exporter which precursors should sit above you.": "आप इसे कैसे बनाते हैं — निर्यातक को बताता है कि आपके ऊपर कौन-से प्रीकर्सर होने चाहिए।",
  "I have my own measured factors": "मेरे अपने मापे गुणांक हैं",
  "I read your documents for this month and fill them in.": "मैं इस महीने के लिए आपके दस्तावेज़ पढ़ती हूँ और उन्हें भर देती हूँ।",
  "I've checked this — file it": "मैंने इसे जाँच लिया है — इसे दर्ज करें",
  "If a revision is needed, you’ll get an email — only the flagged fields unlock.": "अगर संशोधन चाहिए तो आपको ईमेल मिलेगा — केवल चिह्नित फ़ील्ड खुलेंगे।",
  "If any of this is wrong, tell {exporter} before you answer — the figures below are only valid for this good.": "अगर इनमें से कुछ ग़लत है, तो उत्तर देने से पहले {exporter} को बताएँ — नीचे के आँकड़े केवल इसी वस्तु के लिए मान्य हैं।",
  "If it is not reported, the importer is not let off — they fall back to a default set high enough that real data is nearly always cheaper. So what you enter here has a price attached, in both directions.": "अगर रिपोर्ट नहीं किया गया, तो आयातक को छूट नहीं मिलती — वह ऐसे डिफ़ॉल्ट पर आता है जो इतना ऊँचा रखा गया है कि असली डेटा लगभग हमेशा सस्ता पड़ता है। इसलिए जो आप यहाँ दर्ज करते हैं उसकी दोनों दिशाओं में क़ीमत है।",
  "If this good is made from pig iron or DRI, what reduced the iron ore? For a pure scrap-EAF route, choose “None” — that is a complete and expected answer.": "अगर यह वस्तु पिग आयरन या DRI से बनी है, तो लौह अयस्क का अपचयन किसने किया? शुद्ध स्क्रैप-EAF मार्ग के लिए “कोई नहीं” चुनें — यह पूर्ण और अपेक्षित उत्तर है।",
  "If this site has no code yet:": "अगर इस साइट का अभी कोई कोड नहीं है:",
  "In the duct": "डक्ट में",
  "In the meantime, use the code of the nearest listed town — an approximate but real code is more useful to a declarant than a blank field, and the coordinates below pin the exact location anyway.": "इस बीच, सबसे नज़दीकी सूचीबद्ध शहर का कोड उपयोग करें — अनुमानित पर असली कोड घोषणाकर्ता के लिए ख़ाली फ़ील्ड से अधिक उपयोगी है, और नीचे के निर्देशांक वैसे भी सटीक स्थान तय करते हैं।",
  "In the terms your invoices use.": "उन शब्दों में जो आपके बिलों में हैं।",
