  "It goes to the exporter as a request. They decide — nothing is unlocked until they say yes.": "यह निर्यातक के पास अनुरोध के रूप में जाता है। वे तय करते हैं — उनके हाँ कहने तक कुछ नहीं खुलता।",
  "It has to be unique.": "यह अद्वितीय होना चाहिए।",
  "It identifies WHERE the goods were produced. Use the code for the town or port the installation sits in — not your head office, and not the port the goods leave from if that is somewhere else.": "यह बताता है कि माल कहाँ बना। संयंत्र जिस शहर या बंदरगाह में है उसका कोड उपयोग करें — आपका मुख्यालय नहीं, और वह बंदरगाह नहीं जहाँ से माल निकलता है अगर वह कहीं और है।",
  "It is needed": "यह ज़रूरी है",
  "It is not the same thing as the electricity metering point on the card below. That one is a revenue meter; this one is a sampling location on a flue.": "यह नीचे के कार्ड के बिजली मापन बिंदु जैसा नहीं है। वह राजस्व मीटर है; यह फ़्लू पर नमूना लेने की जगह है।",
