  "What a verifier will ask to see behind each figure in this month, grouped by who usually holds it.": "इस महीने के हर आँकड़े के पीछे सत्यापनकर्ता क्या देखना चाहेगा, इस पर समूहित कि आमतौर पर किसके पास होता है।",
  "What can Cera help you with?": "Cera आपकी क्या मदद कर सकती है?",
  "What counts as production": "उत्पादन क्या गिना जाता है",
  "What happened": "क्या हुआ",
