  "What happens next": "आगे क्या होगा",
  "What is measured in the duct is divided by it, so the figure includes fume that escapes the duct.": "डक्ट में जो मापा जाता है उसे इससे भाग दिया जाता है, ताकि आँकड़े में वह धुआँ भी आए जो डक्ट से बच निकलता है।",
  "What is measured in the duct is divided by this to include fume that escapes. From your last field measurement; 100 only if the collection is complete.": "डक्ट में जो मापा गया उसे इससे भाग देकर बच निकले धुएँ को शामिल किया जाता है। आपके अंतिम क्षेत्र-मापन से; 100 केवल तब जब संग्रह पूर्ण हो।",
  "What it is": "यह क्या है",
