  "Where the power comes from, and the meter behind the figure.": "बिजली कहाँ से आती है, और आँकड़े के पीछे का मीटर।",
  "Where this figure came from": "यह आँकड़ा कहाँ से आया",
  "Where your power comes from, and which meter the reported MWh is read off.": "आपकी बिजली कहाँ से आती है, और रिपोर्ट किए MWh किस मीटर से पढ़े जाते हैं।",
  "Which gas": "कौन-सी गैस",
  "Which meter or feeder the reported MWh is read from — the one the invoice evidences.": "रिपोर्ट किए MWh किस मीटर या फ़ीडर से पढ़े जाते हैं — वह जिसका प्रमाण बिल देता है।",
