  "Which processes these figures cover, in the order material moves through them.": "ये आँकड़े किन प्रक्रियाओं को कवर करते हैं, उस क्रम में जिसमें सामग्री उनसे गुज़रती है।",
  "Who sees what.": "कौन क्या देखता है।",
  "Whole meter reading": "पूरे मीटर की रीडिंग",
  "Whose factors": "किसके गुणांक",
  "Why English?": "अंग्रेज़ी क्यों?",
  "Why it is asked.": "यह क्यों पूछा जाता है।",
  "Why this is asked": "यह क्यों पूछा जाता है",
  "Why this one question matters": "यह एक प्रश्न क्यों मायने रखता है",
  "Work it out from deliveries and stock": "डिलीवरी और स्टॉक से निकालें",
  "Work through these in order: Finance, then Operations, then Suppliers.": "इन्हें क्रम से देखें: पहले वित्त, फिर संचालन, फिर आपूर्तिकर्ता।",
  "Worked out from the deliveries below.": "नीचे की डिलीवरी से निकाला गया।",
  "Worked out from the fuel rows above flagged for self-generation.": "स्व-उत्पादन के लिए चिह्नित ऊपर की ईंधन पंक्तियों से निकाला गया।",
  "Worked out from the stock change below.": "नीचे के स्टॉक परिवर्तन से निकाला गया।",
  "Workspace links are personal to one installation and one reporting year. Ask the exporter who contacted you to resend it.": "कार्यक्षेत्र लिंक एक संयंत्र और एक रिपोर्टिंग वर्ष के लिए निजी होते हैं। जिस निर्यातक ने आपसे संपर्क किया उससे इसे दोबारा भेजने को कहें।",
  "Workspace sections": "कार्यक्षेत्र के अनुभाग",
  "Write everything in English.": "सब कुछ अंग्रेज़ी में लिखें।",
  "You are answering for": "आप किसके लिए उत्तर दे रहे हैं",
  "You changed this — the file says": "आपने इसे बदला — फ़ाइल में लिखा है",
  "You produce these goods yourself.": "आप ये वस्तुएँ स्वयं बनाते हैं।",
  "Your analysis. The EU standard is": "आपका विश्लेषण। EU मानक है",
  "Your carbon data": "आपका कार्बन डेटा",
  "Your customer exports this good to the EU. Under CBAM the importer must state the CO₂ embedded in every tonne they bring in, and that figure can only come from the plant that made it. These twelve monthly requests collect it.": "आपका ग्राहक यह वस्तु EU को निर्यात करता है। CBAM के तहत आयातक को हर लाए टन में निहित CO₂ बतानी होती है, और वह आँकड़ा केवल उस संयंत्र से आ सकता है जिसने इसे बनाया। ये बारह मासिक अनुरोध उसे जुटाते हैं।",
  "Your emissions data for this supply chain": "इस आपूर्ति श्रृंखला के लिए आपका उत्सर्जन डेटा",
  "Your figures are checked automatically before you submit and land in your own supplier record, so the next declaration starts pre-filled instead of blank. Colleagues can be assigned the sections that belong to their department.": "आपके आँकड़े जमा करने से पहले अपने-आप जाँचे जाते हैं और आपके अपने आपूर्तिकर्ता रिकॉर्ड में आ जाते हैं, ताकि अगली घोषणा ख़ाली नहीं, पहले से भरी शुरू हो। सहकर्मियों को उनके विभाग के अनुभाग सौंपे जा सकते हैं।",
  "Your figures are checked automatically before you submit, encrypted, and shared only with {exporter} for this declaration. You can invite colleagues to fill the parts that belong to their department.": "आपके आँकड़े जमा करने से पहले अपने-आप जाँचे जाते हैं, एन्क्रिप्ट होते हैं, और इस घोषणा के लिए केवल {exporter} के साथ साझा होते हैं। आप सहकर्मियों को उनके विभाग के हिस्से भरने के लिए आमंत्रित कर सकते हैं।",
  "Your final emissions data for the year": "वर्ष के लिए आपका अंतिम उत्सर्जन डेटा",
  "Your full name": "आपका पूरा नाम",
  "Your own CBAM communication figure.": "आपका अपना CBAM संचार आँकड़ा।",
  "Your own factors": "आपके अपने गुणांक",
  "Your request workspace": "आपका अनुरोध कार्यक्षेत्र",
  "You’re {supplier}. To keep shipping {origin} {sector} into the {destination}, {exporter} has to report the embedded emissions of the goods they buy from you — under {regulation}. This takes about 10 minutes, it’s free, and you don’t need an account.": "आप {supplier} हैं। {origin} से {sector} को {destination} में भेजते रहने के लिए, {exporter} को आपसे ख़रीदे माल का अंतर्निहित उत्सर्जन {regulation} के तहत रिपोर्ट करना होता है। इसमें लगभग 10 मिनट लगते हैं, यह मुफ़्त है, और खाता नहीं चाहिए।",
  "accepted": "स्वीकृत",
  "apply for a new one directly through UNECE, which is the body that issues them. Your customs broker cannot create one for you.": "सीधे UNECE के माध्यम से नया आवेदन करें, जो इन्हें जारी करने वाली संस्था है। आपका कस्टम ब्रोकर आपके लिए नहीं बना सकता।",
  "auto": "स्वतः",
  "can't be withheld from buyers — they're what the CBAM declaration is made of, and holding them back would only mean your goods can't clear. The rest is genuinely optional, and turning it off costs you nothing.": "ख़रीदारों से रोके नहीं जा सकते — CBAM घोषणा इन्हीं से बनती है, और इन्हें रोकने का मतलब केवल यह होगा कि आपका माल क्लियर नहीं हो पाएगा। बाक़ी सचमुच वैकल्पिक हैं, और इसे बंद करने में आपका कुछ नहीं जाता।",
  "carbon in, minus carbon that leaves.": "कार्बन अंदर, घटा कार्बन जो बाहर जाता है।",
  "carbonate": "कार्बोनेट",
