  "{count} instruments declared, in a draft methodology.": "मसौदा कार्यप्रणाली में {count} उपकरण घोषित।",
  "{count} months missing — the table prints incomplete, not smaller.": "{count} महीने ग़ायब — तालिका छोटी नहीं, अधूरी छपती है।",
  "{count} rows the arithmetic refused — the balance would print short by them.": "{count} पंक्तियाँ जिन्हें गणित ने ठुकरा दिया — बैलेंस उतना कम छपेगा।",
  "{count} template fields still blank — {first}": "{count} टेम्पलेट फ़ील्ड अब भी ख़ाली — {first}",
  "{covered} of {total} have a document behind them.": "{total} में से {covered} के पीछे दस्तावेज़ है।",
  "{covered} of {total} submitted months carry fuel rows.": "{total} जमा महीनों में से {covered} में ईंधन पंक्तियाँ हैं।",
  "{done} of {total} read": "{total} में से {done} पढ़े गए",
  "{exporter} needs your carbon data.": "{exporter} को आपका कार्बन डेटा चाहिए।",
  "{exporter} uses a good you make as an input and has asked for your final, verified figure for the reporting year. One request, answered once — nothing is collected month by month. Please answer": "{exporter} आपके बनाए माल को इनपुट के रूप में उपयोग करता है और उसने रिपोर्टिंग वर्ष के लिए आपका अंतिम, सत्यापित आँकड़ा माँगा है। एक अनुरोध, एक बार उत्तर — महीने-दर-महीने कुछ नहीं जुटाया जाता। कृपया उत्तर दें",
  "{from} to {to}. Fixed at creation and printed as it stands.": "{from} से {to} तक। बनाते समय तय हुआ और जैसा है वैसा छपता है।",
  "{n} documents attached": "{n} दस्तावेज़ संलग्न",
  "{n} documents waiting for your check": "{n} दस्तावेज़ आपकी जाँच की प्रतीक्षा में",
  "{n} not needed — won't be filed": "{n} आवश्यक नहीं — दर्ज नहीं होंगे",
  "{n} still need your tick — they stay here for later.": "{n} को अब भी आपके चिह्न की ज़रूरत है — वे बाद के लिए यहीं रहते हैं।",
  "{n} things to fix": "{n} बातें ठीक करनी हैं",
  "{route} is not a production route for {category}. The table will print a contradiction.": "{route} {category} के लिए उत्पादन मार्ग नहीं है। तालिका विरोधाभास छापेगी।",
  "{share}% of the year rests on estimates — past the {threshold}% self-check threshold.": "साल का {share}% अनुमानों पर टिका है — {threshold}% की स्व-जाँच सीमा से ऊपर।",
  "{total} ({required} required)": "{total} ({required} आवश्यक)",
  "± %, from the maker or the calibration certificate.": "± %, निर्माता या अंशांकन प्रमाणपत्र से।",
  "· enter your output in Production to get the per-tonne figure": "· प्रति-टन आँकड़े के लिए उत्पादन में अपना उत्पादन दर्ज करें",
  "· optional": "· वैकल्पिक",
  "· our own installation": "· हमारा अपना संयंत्र",
  "— an EU-accredited verifier reads it. Numbers and dates stay as they are.": "— EU-मान्यता प्राप्त सत्यापनकर्ता इसे पढ़ता है। संख्याएँ और तारीख़ें जैसी हैं वैसी रहती हैं।",
  "— no password, no server session, nothing sent anywhere. It only pre-fills this installation’s details the next time this SAME link is opened on this SAME device or browser.": "— कोई पासवर्ड नहीं, कोई सर्वर सत्र नहीं, कहीं कुछ नहीं भेजा जाता। यह केवल अगली बार इसी लिंक को इसी उपकरण या ब्राउज़र पर खोलने पर इस संयंत्र का विवरण पहले से भरता है।",
  "“Estimated” on its own is a finding. HOW it was estimated — from the mean of the months either side, normalised to production — is an answer.": "अकेला “अनुमानित” एक निष्कर्ष है। कैसे अनुमान लगाया — दोनों ओर के महीनों के माध्य से, उत्पादन के अनुसार सामान्यीकृत — यह उत्तर है।",
  "“Grid — Provincial Electricity Authority (PEA)”, meter PEA 3392011 on main incomer MDB-1.": "“ग्रिड — प्रांतीय बिजली प्राधिकरण (PEA)”, मुख्य इनकमर MDB-1 पर मीटर PEA 3392011।",
