  "{count} more": "{count} और",
  "A few details so we can set up your workspace and CBAM template correctly.": "कुछ विवरण ताकि हम आपका कार्यक्षेत्र और CBAM टेम्पलेट सही तरह तैयार कर सकें।",
  "A few quick questions so Certrace fits how you actually work.": "कुछ छोटे प्रश्न ताकि Certrace आपके काम के तरीक़े के अनुसार बैठे।",
  "Add Certrace on LINE OFFICIAL": "LINE OFFICIAL पर Certrace जोड़ें",
  "All of this stays editable in Settings.": "यह सब सेटिंग्स में संपादन योग्य रहता है।",
  "Almost there — this helps us support you at the right scale.": "बस थोड़ा और — इससे हम आपको सही स्तर पर सहायता दे पाते हैं।",
  "Approximately how many suppliers will you manage in Certrace?": "आप Certrace में लगभग कितने आपूर्तिकर्ताओं का प्रबंधन करेंगे?",
  "Before your workspace opens, a quick check that we have your details right. About two minutes.": "आपका कार्यक्षेत्र खुलने से पहले, एक छोटी जाँच कि हमारे पास आपका विवरण सही है। लगभग दो मिनट।",
  "Enter a real telephone number — digits only, 6 to 14 of them.": "असली टेलीफ़ोन नंबर दर्ज करें — केवल अंक, 6 से 14।",
  "Enter your first name": "अपना पहला नाम दर्ज करें",
  "Enter your last name": "अपना उपनाम दर्ज करें",
  "Everything above is included for the full month. Nothing is filed on your behalf and nothing leaves your workspace until you send it.": "ऊपर का सब कुछ पूरे महीने के लिए शामिल है। आपकी ओर से कुछ दर्ज नहीं होता और आपके भेजने तक कुछ भी आपके कार्यक्षेत्र से बाहर नहीं जाता।",
