  "Analysis": "विश्लेषण",
  "What your goods carry, and what that costs: with your own data, and on the EU default.": "आपके उत्पादों में कितना कार्बन है और उसकी लागत क्या है: आपके अपने डेटा से और EU डिफ़ॉल्ट मान पर।",
