  "Used to show every euro figure in baht, yuan and rupees.": "हर यूरो आँकड़े को थाई बाट, चीनी युआन और भारतीय रुपये में दिखाने के लिए।",
  "The cross-sectoral correction factor is taken as 1: the Commission has not published it in the rules this was built from.": "क्रॉस-सेक्टोरल करेक्शन फ़ैक्टर (CSCF) को 1 माना गया है: जिन नियमों पर यह बना है उनमें आयोग ने इसे अभी प्रकाशित नहीं किया है।",
  "A bought-in precursor's own free allocation is not netted off, so a complex good's cost is never shown lower than it is.": "खरीदी गई पूर्ववर्ती सामग्री का अपना निःशुल्क आवंटन घटाया नहीं गया है, इसलिए जटिल उत्पाद की लागत असल से कम नहीं दिखाई जाती।",
  "{n} product(s) have no EU volume entered, so all the tonnes made are assumed shipped to the EU.": "{n} उत्पादों के लिए EU को भेजी गई मात्रा दर्ज नहीं है, इसलिए माना गया है कि बना हुआ सारा टन EU भेजा गया।",
  "A carbon price paid at home is recorded for {n} product(s). It is shown as claimed and never subtracted.": "{n} उत्पादों के लिए अपने देश में चुकाई गई कार्बन कीमत दर्ज है। इसे दावे के रूप में दिखाया गया है और कभी घटाया नहीं जाता।",
  "Fuel burned and process emissions": "जलाया गया ईंधन और प्रक्रिया उत्सर्जन",
  "of the total": "कुल का",
  "Electricity: reported, not charged for steel and aluminium": "बिजली: इस्पात और एल्युमीनियम के लिए रिपोर्ट होती है, शुल्क नहीं लगता",
  "Electricity: counts toward the certificate bill": "बिजली: प्रमाणपत्र के बिल में गिनी जाती है",
  "Electricity: charged for some goods, not for others": "बिजली: कुछ उत्पादों पर शुल्क लगता है, कुछ पर नहीं",
