  "What an importer pays when nobody gives them a real figure": "जब कोई असली आँकड़ा नहीं देता तब आयातक को जो चुकाना पड़ता है",
  "Total embedded": "कुल अंतर्निहित",
  "Emissions month by month": "महीने-दर-महीने उत्सर्जन",
  "On the tonnes made, against the EU default for the same tonnes": "बनाए गए टन पर, उतने ही टन के EU डिफ़ॉल्ट के मुकाबले",
  "The dark line is what the certificate bill is raised on. Electricity counts only for goods where the rules charge it.": "गहरी रेखा वह है जिस पर प्रमाणपत्र का बिल बनता है। बिजली केवल उन्हीं उत्पादों पर गिनी जाती है जिन पर नियम शुल्क लगाते हैं।",
  "The dark line is what the certificate bill is raised on: direct plus precursors, and electricity only where the rules charge it.": "गहरी रेखा वह है जिस पर प्रमाणपत्र का बिल बनता है: प्रत्यक्ष और पूर्ववर्ती सामग्री, और बिजली केवल वहाँ जहाँ नियम शुल्क लगाते हैं।",
  "Precursors are declared once for the year, so they move with production, not with the month.": "पूर्ववर्ती सामग्री साल में एक बार घोषित होती है, इसलिए वह उत्पादन के साथ बदलती है, महीने के साथ नहीं।",
  "The shaded months are carried forward at this year's rate, not measured.": "छायांकित महीने इस साल की दर से आगे बढ़ाए गए हैं, मापे नहीं गए हैं।",
