  "{amount} on every tonne you ship. An estimate for planning: the declarant buys at the published auction average for the week of import.": "आप जो हर टन भेजते हैं उस पर {amount}। यह योजना के लिए अनुमान है: घोषणाकर्ता आयात के सप्ताह की प्रकाशित नीलामी औसत कीमत पर खरीदता है।",
  "{company} added": "{company} जोड़ा गया",
