  "{count} submitted": "{count} जमा",
  "{count} submitted months are not plotted — their emissions could not be worked out. Monthly data says which reading is missing.": "{count} जमा किए गए महीने चार्ट में नहीं हैं — उनका उत्सर्जन निकाला नहीं जा सका। मासिक डेटा बताता है कि कौन-सी रीडिंग गायब है।",
  "{count} total": "कुल {count}",
  "{counted} of {possible} months submitted.": "{possible} में से {counted} महीने जमा हुए।",
  "{counted} of {possible} months submitted. The figures below are what those months add up to — real, but a part of a year, and a year is what gets declared.": "{possible} में से {counted} महीने जमा हुए। नीचे के आँकड़े उन महीनों का जोड़ हैं — असली, पर साल का एक हिस्सा, और घोषणा पूरे साल की होती है।",
  "{datasets} submitted supplier datasets across {declarations} declarations, costed with the same engine the declaration workspace uses — the Annex II direct-only rule for steel and aluminium, default-value markups where a supplier reported on defaults, and any carbon price already paid deducted. Nothing here is a filed figure.": "{declarations} घोषणाओं में {datasets} जमा किए गए आपूर्तिकर्ता डेटासेट, घोषणा कार्यक्षेत्र वाले उसी इंजन से लागत निकाली गई — इस्पात और एल्युमीनियम के लिए Annex II का केवल-प्रत्यक्ष नियम, जहाँ आपूर्तिकर्ता ने डिफ़ॉल्ट पर रिपोर्ट किया वहाँ डिफ़ॉल्ट मार्क-अप, और पहले चुकाई गई कार्बन कीमत घटाई गई। यहाँ कुछ भी दाखिल किया गया आँकड़ा नहीं है।",
  "{days}d ago": "{days} दिन पहले",
  "{depth} tiers upstream of you": "आपसे ऊपर {depth} स्तर",
  "{done} of 12 months in": "12 में से {done} महीने आ चुके",
  "{entered} of {possible} months have been started but not submitted, so nothing counts toward the year yet. Submit them on Monthly data and these figures fill themselves in.": "{possible} में से {entered} महीने शुरू हुए पर जमा नहीं हुए, इसलिए अभी साल में कुछ भी नहीं गिना जाता। मासिक डेटा में जमा करें, ये आँकड़े अपने आप भर जाएँगे।",
  "{exporter} did not ask for this document. Pick a requested document above if it belongs to one.": "{exporter} ने यह दस्तावेज़ नहीं माँगा था। यदि यह माँगे गए किसी दस्तावेज़ का है, तो ऊपर से उसे चुनें।",
