  "{percent}% of applicable tabs are complete. This percentage is descriptive — it is never used as a gate.": "लागू टैबों में से {percent}% पूर्ण हैं। यह प्रतिशत केवल वर्णन के लिए है — इसे कभी रुकावट के रूप में उपयोग नहीं किया जाता।",
