  "1 submitted month is not plotted — its emissions could not be worked out. Monthly data says which reading is missing.": "जमा किया गया 1 महीना चार्ट में नहीं है — उसका उत्सर्जन निकाला नहीं जा सका। मासिक डेटा बताता है कि कौन-सी रीडिंग गायब है।",
