  "Certrace · EU CBAM compliance for exporters": "Certrace · निर्यातकों के लिए EU CBAM अनुपालन",
  "Certrace classified each product automatically — category, CN / HS codes and the CBAM template come from the catalogue and can't be edited. The checklist below reflects the data points that actually apply to the goods you selected.": "Certrace ने हर उत्पाद को अपने आप वर्गीकृत किया — श्रेणी, CN / HS कोड और CBAM टेम्पलेट सूची से आते हैं और बदले नहीं जा सकते। नीचे की चेकलिस्ट वे डेटा बिंदु दिखाती है जो आपके चुने माल पर सचमुच लागू होते हैं।",
  "Certrace does not notify them yet — tell them.": "Certrace अभी उन्हें सूचित नहीं करता — आप उन्हें बता दें।",
  "Certrace is an AI workflow platform connecting buyers, exporters, and suppliers to automate CBAM carbon data collection — report-ready before buyers even ask.": "Certrace एक AI वर्कफ़्लो प्लेटफ़ॉर्म है जो खरीदारों, निर्यातकों और आपूर्तिकर्ताओं को जोड़कर CBAM कार्बन डेटा संग्रह को स्वचालित करता है — खरीदार के माँगने से पहले ही रिपोर्ट तैयार।",
  "Certrace read your documents": "Certrace ने आपके दस्तावेज़ पढ़े",
  "Chain graded by its weakest link": "सबसे कमज़ोर कड़ी के हिसाब से आँकी गई श्रृंखला",
  "changes requested": "बदलाव माँगे गए",
  "Changing the product changes the CN code and the aggregated goods category this report is filed under. The monthly readings stay — they describe the same furnace — but anything already sent to a verifier under the old code will not match.": "उत्पाद बदलने से इस रिपोर्ट का CN कोड और समग्र माल श्रेणी बदल जाती है। मासिक रीडिंग बनी रहती हैं — वे उसी भट्ठी का वर्णन करती हैं — पर पुराने कोड के तहत सत्यापनकर्ता को भेजा गया कुछ भी अब मेल नहीं खाएगा।",
  "Changing the product changes the CN code and the aggregated goods category this workspace reports under. The monthly readings stay — they describe the same furnace — but anything already sent to a verifier under the old code will not match.": "उत्पाद बदलने से इस कार्यक्षेत्र का CN कोड और समग्र माल श्रेणी बदल जाती है। मासिक रीडिंग बनी रहती हैं — वे उसी भट्ठी का वर्णन करती हैं — पर पुराने कोड के तहत सत्यापनकर्ता को भेजा गया कुछ भी अब मेल नहीं खाएगा।",
