  "Choose dates": "तारीखें चुनें",
  "Choose default or actual. For actual, copy the link and send it.": "डिफ़ॉल्ट या वास्तविक चुनें। वास्तविक के लिए लिंक कॉपी करके भेजें।",
  "Choose one — the official CBAM filing, or a specific buyer's data request. Each has its own qualification checklist, so keep the two separate.": "एक चुनें — आधिकारिक CBAM फ़ाइलिंग, या किसी खास खरीदार का डेटा अनुरोध। दोनों की अपनी पात्रता चेकलिस्ट है, इसलिए दोनों को अलग रखें।",
  "Choose one.": "एक चुनें।",
  "Choose period": "अवधि चुनें",
  "Choose someone": "किसी को चुनें",
  "Choose the carbon-data fields this buyer needs. Recommended fields are pre-selected because buyers commonly ask for them — adjust freely, keeping at least one.": "इस खरीदार को जो कार्बन डेटा फ़ील्ड चाहिए वे चुनें। सुझाए गए फ़ील्ड पहले से चुने हैं क्योंकि खरीदार आम तौर पर उन्हें माँगते हैं — खुलकर बदलें, पर कम से कम एक रखें।",
  "Claimed, never auto-applied. If you claim it, the payment receipt goes in the annual evidence scope.": "दावा किया जाता है, कभी अपने आप लागू नहीं होता। यदि आप दावा करें, तो भुगतान की रसीद वार्षिक साक्ष्य दायरे में जाती है।",
  "Classification": "वर्गीकरण",
  "Classification & report fields": "वर्गीकरण और रिपोर्ट फ़ील्ड",
  "Clear the filters, or start a new declaration — CBAM compliance or a custom buyer request.": "फ़िल्टर हटाएँ, या नई घोषणा शुरू करें — CBAM अनुपालन या कस्टम खरीदार अनुरोध।",
  "Clear them to see every workspace, or widen one — readiness and year are the two that narrow hardest.": "सभी कार्यक्षेत्र देखने के लिए उन्हें हटाएँ, या किसी एक को ढीला करें — तैयारी और वर्ष सबसे ज़्यादा सीमित करते हैं।",
  "Close and save draft": "बंद करें और ड्राफ़्ट सहेजें",
  "Close and save draft — back to the supply chain": "बंद करें और ड्राफ़्ट सहेजें — आपूर्ति श्रृंखला पर वापस",
  "Close the largest gaps with primary data before engaging a verifier.": "सत्यापनकर्ता लगाने से पहले सबसे बड़े अंतराल प्राथमिक डेटा से भर लें।",
  "CN codes included": "शामिल CN कोड",
  "Co-generation or separate generation; fossil or renewable; whether any is exported from a production process": "सह-उत्पादन या अलग उत्पादन; जीवाश्म या नवीकरणीय; क्या कोई बिजली किसी उत्पादन प्रक्रिया से बाहर निर्यात होती है",
  "CO2 capture and transfer": "CO2 कैप्चर और स्थानांतरण",
  "CO2 received from other installations, and exported to them for storage or permanent use": "अन्य संयंत्रों से प्राप्त CO2, और भंडारण या स्थायी उपयोग के लिए उन्हें भेजी गई CO2",
  "CO₂ transfer applies: give the receiving party on the Overview and the tonnes received and sent on in the monthly data.": "CO₂ स्थानांतरण लागू है: ओवरव्यू में प्राप्त करने वाले पक्ष को, और मासिक डेटा में प्राप्त व भेजे गए टन दर्ज करें।",
  "CO2 transfer: the identity and contact details of the responsible person at the receiving installation or transport infrastructure": "CO2 स्थानांतरण: प्राप्त करने वाले संयंत्र या परिवहन अवसंरचना पर ज़िम्मेदार व्यक्ति की पहचान और संपर्क विवरण",
  "Coke and coal burned as reductant. The most carbon-intensive steel route.": "अपचायक के रूप में जलाया गया कोक और कोयला। सबसे अधिक कार्बन-गहन इस्पात मार्ग।",
