  "Company → installation → reporting year → product report. The installation holds what is entered once; a product report is one CN code for one reporting year — the screen you monitor each month.": "कंपनी → संयंत्र → रिपोर्टिंग वर्ष → उत्पाद रिपोर्ट। संयंत्र वह रखता है जो एक बार दर्ज होता है; उत्पाद रिपोर्ट एक रिपोर्टिंग वर्ष का एक CN कोड है — वह स्क्रीन जिसे आप हर महीने देखते हैं।",
  "Compare the values with the document, then tap here. Unticked files are not filed.": "मानों को दस्तावेज़ से मिलाएँ, फिर यहाँ टैप करें। जिन फ़ाइलों पर निशान नहीं है वे दाखिल नहीं होतीं।",
