  "Defensible when consumption tracks output closely. Show the ratio you used and the period it came from.": "तब टिकाऊ जब खपत उत्पादन के साथ कसकर चलती हो। जो अनुपात आपने उपयोग किया और वह किस अवधि से आया, दिखाइए।",
  "Deliberately unflattering by design, which is why it is safe. Expect no challenge, but it costs you.": "जानबूझकर अप्रिय बनाया गया है, इसीलिए सुरक्षित है। चुनौती की उम्मीद नहीं, पर इसकी आपको कीमत चुकानी पड़ती है।",
