  "Derived automatically: own direct + own indirect + precursor contribution": "अपने आप निकला: अपना प्रत्यक्ष + अपना अप्रत्यक्ष + पूर्ववर्ती सामग्री का योगदान",
  "Derived from the MMD's data-gap register. Nothing to fill in — it moves when the gaps do.": "MMD के डेटा-अंतराल रजिस्टर से लिया गया। कुछ भरना नहीं — अंतराल बदलने पर यह भी बदलता है।",
