  "Download Monitoring Methodology Documentation": "निगरानी पद्धति दस्तावेज़ीकरण डाउनलोड करें",
  "Download one, then drop it above. Each holds only a few readings — enough to see how it works.": "एक डाउनलोड करें और ऊपर डाल दें। हर एक में बस कुछ रीडिंग हैं — यह समझने के लिए काफ़ी कि यह कैसे चलता है।",
  "Downloading documents for {name}…": "{name} के दस्तावेज़ डाउनलोड हो रहे हैं…",
  "Downloading report for {name}…": "{name} की रिपोर्ट डाउनलोड हो रही है…",
  "draft": "ड्राफ़्ट",
  "Draft — not finalised": "ड्राफ़्ट — अंतिम नहीं",
