  "Draft pack downloaded": "ड्राफ़्ट पैक डाउनलोड हुआ",
  "Draw the line around what you are reporting. A verifier's first question is always what happens on this site that is NOT in these numbers, and why that is correct.": "जो आप रिपोर्ट कर रहे हैं उसके चारों ओर रेखा खींचें। सत्यापनकर्ता का पहला सवाल हमेशा यही होता है कि इस साइट पर ऐसा क्या होता है जो इन आँकड़ों में नहीं है, और वह सही क्यों है।",
  "Drawn from the public grid. Factor is the published country default — locked, never typed.": "सार्वजनिक ग्रिड से ली गई। कारक प्रकाशित देश-डिफ़ॉल्ट है — बंद, कभी टाइप नहीं किया जाता।",
  "Drop this month's bills, fuel invoices and ERP exports. AI reads each one, files it and fills the matching figures. You check everything before it is saved — AI can make mistakes.": "इस महीने के बिल, ईंधन इनवॉइस और ERP एक्सपोर्ट यहाँ डालें। AI हर एक को पढ़ता है, फ़ाइल करता है और मिलते आँकड़े भरता है। सहेजने से पहले आप सब जाँचें — AI से गलती हो सकती है।",
  "due": "देय",
  "Due": "देय",
  "Due now": "अब देय",
  "e.g. ABC Buyer Carbon Data Request": "जैसे ABC खरीदार कार्बन डेटा अनुरोध",
  "e.g. Annual CBAM carbon data for our EU steel exports. Please report at installation level.": "जैसे: हमारे EU इस्पात निर्यात का वार्षिक CBAM कार्बन डेटा। कृपया संयंत्र स्तर पर रिपोर्ट करें।",
  "e.g. CBAM 2026 Annual": "जैसे CBAM 2026 वार्षिक",
  "e.g. Eastern Steel Mill": "जैसे ईस्टर्न स्टील मिल",
  "e.g. Please use installation-level actual data where possible. Contact us if you need help.": "जैसे: कृपया जहाँ संभव हो संयंत्र-स्तर का वास्तविक डेटा उपयोग करें। मदद चाहिए तो हमसे संपर्क करें।",
  "e.g. Steel billet": "जैसे स्टील बिलेट",
  "e.g. Thai Special Steel": "जैसे थाई स्पेशल स्टील",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — a declarant addendum where electricity goes to the EU — and, beside them, the verification reports of your precursors' installations and the supporting evidence. It covers every product the site makes, and downloads once all of it is complete.": "आप जिस भी संयंत्र की रिपोर्ट देते हैं वह साल में एक पैकेज सौंपता है: निगरानी योजना, संचालक की उत्सर्जन रिपोर्ट और सार रिपोर्ट — जहाँ बिजली EU को जाती है वहाँ घोषणाकर्ता परिशिष्ट — और उनके साथ आपकी पूर्ववर्ती सामग्री के संयंत्रों की सत्यापन रिपोर्टें और सहायक साक्ष्य। यह साइट के हर उत्पाद को कवर करता है, और सब कुछ पूर्ण होने पर ही डाउनलोड होता है।",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — and a declarant addendum where electricity goes to the EU. It covers every product the site makes, and downloads once all of it is complete.": "आप जिस भी संयंत्र की रिपोर्ट देते हैं वह साल में एक पैकेज सौंपता है: निगरानी योजना, संचालक की उत्सर्जन रिपोर्ट और सार रिपोर्ट — और जहाँ बिजली EU को जाती है वहाँ घोषणाकर्ता परिशिष्ट। यह साइट के हर उत्पाद को कवर करता है, और सब कुछ पूर्ण होने पर ही डाउनलोड होता है।",
  "Each is filed against the figure it supports.": "हर एक उसी आँकड़े के विरुद्ध फ़ाइल होता है जिसका वह समर्थन करता है।",
  "Each one links to the screen that fixes it.": "हर एक उस स्क्रीन से जुड़ा है जो उसे ठीक करती है।",
  "Each product has its own parameters.": "हर उत्पाद के अपने पैरामीटर हैं।",
  "Economic activity": "आर्थिक गतिविधि",
