  "Electricity emissions": "बिजली उत्सर्जन",
  "Electricity emissions are not counted for {product}, so no electricity document is required.": "{product} के लिए बिजली उत्सर्जन नहीं गिना जाता, इसलिए बिजली का कोई दस्तावेज़ ज़रूरी नहीं।",
  "Electricity from different sources, in which quantities — and the supplier's name and country where another installation supplies it": "अलग-अलग स्रोतों की बिजली और उनकी मात्राएँ — और जहाँ कोई अन्य संयंत्र आपूर्ति करता है वहाँ आपूर्तिकर्ता का नाम और देश",
