  "Map suppliers to each product, then add the production lots you bought in this period. Each lot keeps its own quantity and optional production period, so the embedded-emissions calculation stays fully traceable.": "आपूर्तिकर्ताओं को हर उत्पाद से जोड़ें, फिर इस अवधि में खरीदे उत्पादन लॉट जोड़ें। हर लॉट अपनी मात्रा और वैकल्पिक उत्पादन अवधि रखता है, इसलिए अंतर्निहित उत्सर्जन की गणना पूरी तरह पता लगाने योग्य रहती है।",
