  "Name any part of the data flow done by someone else — a laboratory, a metering contractor — and how it is controlled.": "डेटा प्रवाह का जो भी हिस्सा किसी और ने किया — प्रयोगशाला, मीटरिंग ठेकेदार — और उसे कैसे नियंत्रित किया जाता है, बताएँ।",
  "Name it as your team names it": "इसे वही नाम दें जो आपकी टीम देती है",
