  "Name the systems that process the data and say how they are tested, controlled and maintained.": "डेटा संसाधित करने वाले सिस्टम के नाम बताएँ और यह भी कि उनका परीक्षण, नियंत्रण और रखरखाव कैसे होता है।",
  "Name the utility or installation that supplies the electricity; for a power purchase agreement, name the producer.": "बिजली देने वाली यूटिलिटी या संयंत्र का नाम बताएँ; बिजली खरीद समझौते में उत्पादक का नाम बताएँ।",
  "Name the utility or installation that supplies the electricity: choose the supply in the methodology, or name the supplier installation on the month's electricity row.": "बिजली देने वाली यूटिलिटी या संयंत्र का नाम बताएँ: पद्धति में आपूर्ति चुनें, या महीने की बिजली पंक्ति पर आपूर्ति करने वाले संयंत्र का नाम लिखें।",
  "Named manager · agreed SLA": "नामित प्रबंधक · तय SLA",
  "Natural gas (pipeline) for the ladle preheaters, and diesel for the standby generator and yard handling equipment. Both appear as fuel rows every month; the methodology lists them so a month with an unexpected third fuel is visible as an exception.": "पाइपलाइन प्राकृतिक गैस लैडल प्रीहीटर के लिए, और डीज़ल स्टैंडबाय जनरेटर और यार्ड के उपकरणों के लिए। दोनों हर महीने ईंधन पंक्तियों में आते हैं; पद्धति इन्हें सूचीबद्ध करती है ताकि किसी महीने अप्रत्याशित तीसरा ईंधन आए तो अपवाद के रूप में दिख जाए।",
  "Natural gas consumption": "प्राकृतिक गैस खपत",
  "Natural gas invoice for March 2026 — 185,400 Sm³ delivered at RY-DP-014.": "मार्च 2026 का प्राकृतिक गैस बिल — RY-DP-014 पर 185,400 Sm³ पहुँचाई गई।",
  "Natural gas volume": "प्राकृतिक गैस की मात्रा",
  "Natural gas, other fossil fuels or biomass used as the reducing agent and for heating. Hydrogen used as a reductant is a precursor, not a fuel.": "अपचायक और ताप के लिए उपयोग हुई प्राकृतिक गैस, अन्य जीवाश्म ईंधन या बायोमास। अपचायक के रूप में हाइड्रोजन पूर्ववर्ती सामग्री है, ईंधन नहीं।",
  "needs a part-year to project": "अनुमान के लिए आंशिक वर्ष चाहिए",
