  "No annual paperwork attached yet — the licence, calibration records and any carbon-price receipt live on the Readiness tab, outside the twelve months.": "अभी कोई वार्षिक कागज़ात संलग्न नहीं — लाइसेंस, अंशांकन रिकॉर्ड और कार्बन कीमत की रसीद तैयारी टैब पर रहती हैं, बारह महीनों के बाहर।",
