  "No cap on your plan.": "आपके प्लान पर कोई सीमा नहीं।",
  "No carbon price paid in the country of origin. A valid and common answer — record it rather than leaving the field empty.": "मूल देश में कोई कार्बन कीमत नहीं चुकाई गई। यह एक वैध और आम उत्तर है — फ़ील्ड खाली छोड़ने के बजाय इसे दर्ज करें।",
  "No certificate price is on file for this period yet.": "इस अवधि का प्रमाणपत्र मूल्य अभी उपलब्ध नहीं है।",
  "No checklist row to file to.": "फ़ाइल करने के लिए कोई चेकलिस्ट पंक्ति नहीं।",
  "No checks assigned right now.": "अभी कोई जाँच सौंपी नहीं गई।",
  "No contact on file": "कोई संपर्क दर्ज नहीं",
