  "Not late yet — due {date}": "अभी देर नहीं — देय {date}",
  "Not needed for this workspace": "इस कार्यक्षेत्र के लिए आवश्यक नहीं",
  "Not ready": "तैयार नहीं",
  "Not recognised": "पहचाना नहीं गया",
  "Not requested by {exporter}": "{exporter} ने नहीं माँगा",
  "Not requested yet": "अभी माँगा नहीं गया",
