  "Plausible on its own, unusual next to the rest of the year. Worth one look, then carry on.": "अपने आप में विश्वसनीय, पर साल के बाकी हिस्से के पास असामान्य। एक नज़र डालें और आगे बढ़ें।",
  "Please report at installation level using actual data where you have it. If you only have default factors, mark the method as “default”. Reach out if anything is unclear — we'd rather help than receive a guess.": "कृपया जहाँ आपके पास हो वहाँ संयंत्र स्तर पर वास्तविक डेटा के साथ रिपोर्ट करें। अगर आपके पास केवल डिफ़ॉल्ट कारक हैं, तो विधि को ‘डिफ़ॉल्ट’ चिह्नित करें। कुछ अस्पष्ट हो तो संपर्क करें — हम अंदाज़ा पाने से ज़्यादा मदद करना पसंद करेंगे।",
