  "Report what was received in the month, not what was consumed from stock. Enter 0 if none arrived — a blank is read as a gap, and a gap understates the finished good.": "महीने में जो प्राप्त हुआ वह रिपोर्ट करें, स्टॉक से जो खपा वह नहीं। कुछ नहीं आया तो 0 लिखें — खाली को अंतराल माना जाता है, और अंतराल तैयार माल को कम आँकता है।",
