  "unnamed supplier": "बिना नाम का आपूर्तिकर्ता",
  "Until all {total} are answered the product reports of this site read Blocked. You can still enter months and precursors.": "जब तक सभी {total} का उत्तर नहीं मिलता, इस साइट की उत्पाद रिपोर्टें ‘अवरुद्ध’ दिखती हैं। आप महीने और पूर्ववर्ती सामग्री फिर भी दर्ज कर सकते हैं।",
  "Until all {total} are answered, every product report of this site stays Blocked and the report package stays locked — the reports open with these facts. Monthly data and precursors can still be entered meanwhile.": "जब तक सभी {total} का उत्तर नहीं मिलता, इस साइट की हर उत्पाद रिपोर्ट ‘अवरुद्ध’ रहती है और रिपोर्ट पैकेज बंद रहता है — रिपोर्टें इन्हीं तथ्यों से खुलती हैं। इस बीच मासिक डेटा और पूर्ववर्ती सामग्री दर्ज की जा सकती है।",
  "Update": "अपडेट",
