  "Upload a diagram": "आरेख अपलोड करें",
  "Uploaded — needs binding": "अपलोड हुआ — जोड़ना बाकी",
  "Urea": "यूरिया",
  "Usually none in scope — scrap is zero-rated. Alloying additions can matter.": "आम तौर पर दायरे में कुछ नहीं — स्क्रैप शून्य-दर्जे का है। मिश्रधातु योजक मायने रख सकते हैं।",
  "Usually none in scope. Scrap is zero-rated, so nothing carries embedded emissions into the furnace.": "आम तौर पर दायरे में कुछ नहीं। स्क्रैप शून्य-दर्जे का है, इसलिए भट्ठी में कोई अंतर्निहित उत्सर्जन लेकर नहीं जाता।",
  "Usually none in scope. Scrap is zero-rated.": "आम तौर पर दायरे में कुछ नहीं। स्क्रैप शून्य-दर्जे का है।",
