  "How you know your numbers": "आप अपने आँकड़े कैसे जानते हैं",
  "Monitoring methodology": "निगरानी पद्धति",
  "No inputs are declared as assumptions.": "कोई भी इनपुट धारणा के रूप में घोषित नहीं है।",
  "Note": "टिप्पणी",
  "Nothing recorded yet.": "अभी कुछ दर्ज नहीं।",
  "The method is unchanged between these versions. Same method year over year is exactly what the consistency assertion is looking for.": "इन संस्करणों के बीच पद्धति अपरिवर्तित है। साल-दर-साल वही पद्धति ठीक वही है जो संगति कथन खोजता है।",
  "This is the first thing a verifier asks for — before any figure is tested. Everything below is generated from what you have already entered; read it, correct what is wrong, and finalise a version.": "सत्यापनकर्ता सबसे पहले यही माँगता है — किसी आँकड़े को परखने से पहले। नीचे का सब कुछ आपके पहले दर्ज किए से बना है; इसे पढ़ें, जो गलत है उसे सुधारें, और एक संस्करण अंतिम करें।",
  "Declaration view": "घोषणा दृश्य",
  "Certificate exposure, carbon-price spend and supplier cost stay on your side of the line. The verifier sees provenance, attestations and the derivation behind every figure — which is everything their opinion depends on and nothing of your commercial position. Suppliers can withhold their process from a buyer; they can never withhold it from the verifier.": "प्रमाणपत्र एक्सपोज़र, कार्बन-मूल्य खर्च और आपूर्तिकर्ता लागत आपकी ओर रेखा के भीतर रहते हैं। सत्यापनकर्ता स्रोत, प्रमाणन और हर आँकड़े के पीछे की व्युत्पत्ति देखता है — यानी वह सब जिस पर उसकी राय टिकी है, और आपकी व्यावसायिक स्थिति का कुछ नहीं। आपूर्तिकर्ता खरीदार से अपनी प्रक्रिया रोक सकते हैं; सत्यापनकर्ता से कभी नहीं।",
  "Dataset hash": "डेटासेट हैश",
  "Every assertion is answerable from what is in the portal. That is the definition of a dossier that passes easily.": "हर कथन का उत्तर पोर्टल में मौजूद चीज़ों से दिया जा सकता है। आसानी से पास होने वाली डॉसियर की परिभाषा यही है।",
  "Frozen calculation": "फ़्रीज़ की गई गणना",
  "MVP note: the verifier link is an encoding, not authentication. Production links must be server-issued, signed, expiring and revocable — see docs/SECURITY.md.": "MVP नोट: सत्यापनकर्ता लिंक एक एन्कोडिंग है, प्रमाणीकरण नहीं। उत्पादन लिंक सर्वर-जारी, हस्ताक्षरित, समयबद्ध और रद्द करने योग्य होने चाहिए — docs/SECURITY.md देखें।",
  "Ordered by the seven assertions a verifier works through. Anything marked unanswered below is a question they will ask — cheaper to close now than during the engagement.": "उन सात कथनों के क्रम में जिनसे होकर सत्यापनकर्ता गुज़रता है। नीचे ‘अनुत्तरित’ चिह्नित हर चीज़ एक प्रश्न है जो वे पूछेंगे — अभी बंद करना काम के दौरान करने से सस्ता है।",
  "Sign-off": "हस्ताक्षर",
