  "Click the link there to finish the switch — nothing changes until you confirm, and your account, history and org access stay exactly the same.": "बदलाव पूरा करने के लिए वहाँ का लिंक क्लिक करें — आपके पुष्टि करने तक कुछ नहीं बदलता, और आपका खाता, इतिहास और संगठन पहुँच बिल्कुल वही रहते हैं।",
  "Configure how cookies are used across the platform — essential cookies keep you signed in; the rest are optional.": "तय करें कि पूरे प्लेटफ़ॉर्म पर कुकीज़ कैसे उपयोग हों — ज़रूरी कुकीज़ आपको साइन-इन रखती हैं; बाकी वैकल्पिक हैं।",
