  "Essential cookies": "ज़रूरी कुकीज़",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Add as many as you run.": "आप जो भी साइट खुद चलाते हैं। उन्हें यहाँ एक बार पंजीकृत करें और उनका मासिक डेटा आपूर्तिकर्ता के पास जाने के बजाय आपके इनबॉक्स में आएगा। जितनी चलाते हैं उतनी जोड़ें।",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers {cap} sites.": "आप जो भी साइट खुद चलाते हैं। उन्हें यहाँ एक बार पंजीकृत करें और उनका मासिक डेटा आपूर्तिकर्ता के पास जाने के बजाय आपके इनबॉक्स में आएगा। आपका प्लान {cap} साइटें कवर करता है।",
  "Every site you operate yourself. Register them here once and their monthly data lands in your inbox instead of going out to a supplier. Your plan covers one site.": "आप जो भी साइट खुद चलाते हैं। उन्हें यहाँ एक बार पंजीकृत करें और उनका मासिक डेटा आपूर्तिकर्ता के पास जाने के बजाय आपके इनबॉक्स में आएगा। आपका प्लान एक साइट कवर करता है।",
  "For your security, we verify it's really you before changing anything.": "आपकी सुरक्षा के लिए, कुछ भी बदलने से पहले हम जाँचते हैं कि वाकई आप ही हैं।",
  "generated automatically from your name.": "आपके नाम से अपने-आप बना।",
  "Google connected.": "Google जुड़ गया।",
  "Helps us see which parts of Certrace actually get used.": "हमें दिखाता है कि Certrace के कौन-से हिस्से सचमुच उपयोग होते हैं।",
  "Learn how your personal data is collected, used and protected in accordance with applicable laws.": "जानें कि लागू कानूनों के अनुसार आपका व्यक्तिगत डेटा कैसे एकत्र, उपयोग और सुरक्षित किया जाता है।",
