  "These are the facts a verifier asks for about a producing site. Entered once here, reused by every product report.": "ये वे तथ्य हैं जो सत्यापनकर्ता किसी उत्पादन साइट के बारे में पूछता है। यहाँ एक बार दर्ज, हर उत्पाद रिपोर्ट में दोबारा उपयोग।",
  "this device": "यह डिवाइस",
  "This ID is permanent and never changes — your declarations, suppliers and seats stay attached to it even if the email below changes. If the person who set up this account leaves the company, ownership can move to a new email without losing any history.": "यह ID स्थायी है और कभी नहीं बदलती — नीचे का ईमेल बदल जाए तब भी आपकी घोषणाएँ, आपूर्तिकर्ता और सीटें इससे जुड़ी रहती हैं। अगर इस खाते को सेट करने वाला व्यक्ति कंपनी छोड़ दे, तो स्वामित्व बिना इतिहास खोए नए ईमेल पर जा सकता है।",
  "Unlimited": "असीमित",
