  "No account needed. Send marks it as asked and copies the link — paste it wherever you reach them.": "खाते की ज़रूरत नहीं। ‘भेजें’ इसे माँगा हुआ दर्ज करता है और लिंक कॉपी करता है — जहाँ भी उनसे संपर्क करें वहाँ चिपका दें।",
