  "months in": "महीने आए",
  "Months in": "आए महीने",
  "No goods are being verified at this supplier yet. Create a product report for one of their plants and its twelve months start here.": "इस आपूर्तिकर्ता पर अभी कोई माल सत्यापित नहीं हो रहा। उनके किसी प्लांट के लिए उत्पाद रिपोर्ट बनाएँ और उसके बारह महीने यहीं से शुरू होते हैं।",
  "No installations recorded for this supplier yet. A product report is scoped to a plant, so until one exists there is nothing to ask them for.": "इस आपूर्तिकर्ता के लिए अभी कोई संयंत्र दर्ज नहीं। उत्पाद रिपोर्ट किसी प्लांट तक सीमित होती है, इसलिए जब तक कोई न हो, उनसे माँगने को कुछ नहीं।",
  "Not connected yet": "अभी जुड़ा नहीं",
  "Not in your directory.": "आपकी निर्देशिका में नहीं।",
  "Nothing is filed under “{slug}”. It may have been removed, or the link may be from another account.": "“{slug}” के अंतर्गत कुछ फ़ाइल नहीं है। हो सकता है वह हटा दिया गया हो, या लिंक किसी और खाते का हो।",
  "Nothing sent yet. Open the product report's Monthly data tab and send a month to start the trail.": "अभी कुछ नहीं भेजा गया। उत्पाद रिपोर्ट का मासिक डेटा टैब खोलें और कोई महीना भेजें, तब रिकॉर्ड शुरू होता है।",
  "Nothing to generate yet.": "अभी बनाने को कुछ नहीं।",
  "of what was asked": "जो माँगा गया उसका",
  "One document per good, built from what this supplier has actually sent you. Generated on download rather than stored, so it always says what the product report says today.": "हर माल के लिए एक दस्तावेज़, जो इस आपूर्तिकर्ता द्वारा आपको असल में भेजे गए से बना है। संग्रहित करने के बजाय डाउनलोड पर बनता है, इसलिए वह हमेशा वही कहता है जो उत्पाद रिपोर्ट आज कहती है।",
  "sent {date}": "{date} को भेजा गया",
  "Suppliers": "आपूर्तिकर्ता",
  "What is being verified at this supplier's plants, and every month you have actually sent them. A month appears once it has gone out and leaves the late band once it is in.": "इस आपूर्तिकर्ता के प्लांटों पर क्या सत्यापित हो रहा है, और आपने उन्हें असल में कौन-से महीने भेजे। महीना भेजे जाने के बाद दिखता है और आ जाने पर देर वाले दायरे से हट जाता है।",
  "{count} suppliers have no installation recorded.": "{count} आपूर्तिकर्ताओं के लिए कोई संयंत्र दर्ज नहीं।",
  "{n}d overdue": "{n} दिन देर",
  "1 supplier has no installation recorded.": "1 आपूर्तिकर्ता के लिए कोई संयंत्र दर्ज नहीं।",
  "A product report is scoped to a plant, so until one is added there is nothing to ask them for. Open a supplier and add the plant that makes your good.": "उत्पाद रिपोर्ट किसी प्लांट तक सीमित होती है, इसलिए जब तक कोई जोड़ा न जाए, उनसे माँगने को कुछ नहीं। कोई आपूर्तिकर्ता खोलें और वह प्लांट जोड़ें जो आपका माल बनाता है।",
  "across every supplier": "सभी आपूर्तिकर्ताओं में",
  "Add supplier": "आपूर्तिकर्ता जोड़ें",
  "Data suppliers": "डेटा आपूर्तिकर्ता",
  "due in {n}d": "{n} दिन में देय",
  "Every company you collect data from, and the plants each of them runs. A supplier answers through a link each month — no account, no seat, no fee.": "हर कंपनी जिससे आप डेटा लेते हैं, और उनमें से हर एक जो प्लांट चलाती है। आपूर्तिकर्ता हर महीने एक लिंक से उत्तर देता है — न खाता, न सीट, न शुल्क।",
  "free and unlimited on every plan": "हर प्लान पर निःशुल्क और असीमित",
  "Next page": "अगला पेज",
  "No precursor suppliers match “{query}”.": "“{query}” से मेल खाता कोई पूर्ववर्ती सामग्री आपूर्तिकर्ता नहीं।",
  "No precursor suppliers yet — they are added from a product report's Supply Chain — Precursor Tree.": "अभी कोई पूर्ववर्ती सामग्री आपूर्तिकर्ता नहीं — वे उत्पाद रिपोर्ट के आपूर्ति श्रृंखला — पूर्ववर्ती सामग्री वृक्ष से जोड़े जाते हैं।",
  "No suppliers match “{query}”.": "“{query}” से मेल खाता कोई आपूर्तिकर्ता नहीं।",
  "No suppliers yet. Add the first company you buy from.": "अभी कोई आपूर्तिकर्ता नहीं। जिस पहली कंपनी से आप खरीदते हैं उसे जोड़ें।",
