  "product reports on their plants": "उनके प्लांटों पर उत्पाद रिपोर्टें",
  "saved on their own device after a submission, not a real login.": "जमा करने के बाद उनके अपने डिवाइस पर सहेजा गया, असली लॉगिन नहीं।",
