  "They join your team list and can be assigned to any check. We email them an invite with scoped, read-only access — they never see anything outside what you share.": "वे आपकी टीम सूची से जुड़ते हैं और किसी भी जाँच में नियुक्त किए जा सकते हैं। हम उन्हें सीमित, केवल-पढ़ने की पहुँच वाला आमंत्रण ईमेल करते हैं — आपके साझा किए से बाहर वे कुछ नहीं देखते।",
