  "Rotterdam Steel Import BV": "Rotterdam Steel Import BV",
  "The EU importer this consignment is going to. Recorded once, then picked on every shipment to them.": "वह EU आयातक जिसे यह खेप जा रही है। एक बार दर्ज, फिर उन्हें जाने वाली हर खेप पर चुना जाता है।",
  "The EU importer, as it appears on your invoice.": "EU आयातक, जैसा आपके चालान पर दिखता है।",
