  "Conservativeness is one of the seven things a verifier tests. The question is not whether you estimated — it is whether the estimate could have come out in your favour.": "रूढ़िवादिता उन सात चीज़ों में से एक है जो सत्यापनकर्ता परखता है। सवाल यह नहीं कि आपने अनुमान लगाया — सवाल यह है कि क्या अनुमान आपके पक्ष में आ सकता था।",
  "Data gap — period end": "डेटा अंतराल — अवधि का अंत",
