  "A shipment is priced by the calculation version valid on the day it left. Tonnes shipped before any version was frozen have no approved figure yet — they are shown separately rather than counted as zero.": "खेप का मूल्य उस दिन लागू गणना संस्करण से तय होता है जब वह गई। किसी संस्करण के फ़्रीज़ होने से पहले भेजे टन का अभी कोई मंज़ूर आँकड़ा नहीं — उन्हें शून्य गिनने के बजाय अलग दिखाया जाता है।",
