  "No precursor suppliers on file yet.": "अभी कोई पूर्ववर्ती सामग्री आपूर्तिकर्ता दर्ज नहीं।",
  "Supplier & precursor chain health": "आपूर्तिकर्ता और पूर्ववर्ती सामग्री श्रृंखला की सेहत",
  "A trust score exists for declarations, but it reads a declaration’s supplier-review rollup — a product report has no equivalent. Rather than invent a second, differently-defined score for this page, this widget stays empty until one calculation covers both.": "घोषणाओं के लिए एक भरोसा स्कोर है, पर वह घोषणा का आपूर्तिकर्ता-समीक्षा सार पढ़ता है — उत्पाद रिपोर्ट का ऐसा कोई समतुल्य नहीं है। इस पेज के लिए अलग तरह परिभाषित दूसरा स्कोर गढ़ने के बजाय, यह विजेट तब तक खाली रहता है जब तक एक गणना दोनों को कवर न करे।",
