  "A declaration fans out into one report per supplier × product. This one has no supplier-and-product pairs recorded, so there is nothing to collect against — add them in the declaration's own setup and they will appear here.": "एक घोषणा हर आपूर्तिकर्ता × उत्पाद की एक रिपोर्ट में फैलती है। इसमें आपूर्तिकर्ता-और-उत्पाद की कोई जोड़ी दर्ज नहीं, इसलिए जुटाने को कुछ नहीं — घोषणा के अपने सेटअप में उन्हें जोड़ें और वे यहाँ दिखेंगे।",
