  "One per supplier × product. Each one is verified separately.": "हर आपूर्तिकर्ता × उत्पाद के लिए एक। हर एक अलग से सत्यापित होती है।",
  "Open declaration setup": "घोषणा सेटअप खोलें",
  "Open workflow": "कार्यप्रवाह खोलें",
  "Review, sign-off, filing and dispatch": "समीक्षा, हस्ताक्षर, फ़ाइलिंग और प्रेषण",
  "Suppliers and Reports stay in the left nav — they are quick, frequent jobs, and burying them under a declaration would guarantee they never get done.": "आपूर्तिकर्ता और रिपोर्टें बाएँ नेविगेशन में रहती हैं — वे तेज़, बार-बार के काम हैं, और उन्हें किसी घोषणा के नीचे दबाने से पक्का है कि वे कभी नहीं होंगे।",
  "The EU importer's Authorised CBAM Declarant is the party that actually files with the Registry. Until this declaration names one, with an EORI, everything collected below it has nowhere to go.": "EU आयातक का अधिकृत CBAM घोषणाकर्ता वही पक्ष है जो रजिस्ट्री में सचमुच दाखिल करता है। जब तक यह घोषणा EORI के साथ किसी को नामित नहीं करती, नीचे जुटाई हर चीज़ के जाने की जगह नहीं।",
  "The full declaration workflow — supplier submissions, the AI check, cost and carbon, the Registry XML, and sending the Communication Template to the buyer. Everything that happens once the reports above are complete.": "पूरा घोषणा कार्यप्रवाह — आपूर्तिकर्ता जमा, AI जाँच, लागत और कार्बन, रजिस्ट्री XML, और खरीदार को संचार टेम्पलेट भेजना। ऊपर की रिपोर्टें पूर्ण होने के बाद होने वाला सब कुछ।",
  "This declaration recorded a material name but never a CN code. Pick the good and the annual report can be created.": "इस घोषणा में एक सामग्री का नाम दर्ज है पर CN कोड कभी नहीं। माल चुनें और वार्षिक रिपोर्ट बन सकती है।",
  "Verification-ready": "सत्यापन-तैयार",
