  "An estimate for planning, not a filed figure — the declarant buys certificates at the published auction average for the week of import, and applies the official exchange rate. Change the price above to model a different scenario.": "योजना के लिए अनुमान, दाखिल आँकड़ा नहीं — घोषणाकर्ता आयात वाले सप्ताह के प्रकाशित नीलामी औसत पर प्रमाणपत्र खरीदता है और आधिकारिक विनिमय दर लगाता है। अलग परिदृश्य के लिए ऊपर की कीमत बदलें।",
