  "CBAM-critical: this supplier carries a major share of the declaration's embedded emissions — the package can't be filed without them.": "CBAM-महत्वपूर्ण: यह आपूर्तिकर्ता घोषणा के अंतर्निहित उत्सर्जन का बड़ा हिस्सा ले जाता है — इसके बिना पैकेज दाखिल नहीं हो सकता।",
  "Certificate price in EUR per tonne CO2e": "प्रमाणपत्र मूल्य, EUR प्रति टन CO2e",
  "Certrace never files with the CBAM authority directly — only the EU buyer's Authorised CBAM Declarant can do that. What actually reaches the regulator is either a push into the CBAM Registry's": "Certrace कभी सीधे CBAM प्राधिकरण में दाखिल नहीं करता — केवल EU खरीदार का अधिकृत CBAM घोषणाकर्ता कर सकता है। नियामक तक असल में जो पहुँचता है वह या तो CBAM रजिस्ट्री में एक पुश है:",
  "Changes requested": "बदलाव माँगे गए",
  "Click an issue to open that supplier's submission and request a revision.": "किसी समस्या पर क्लिक करके उस आपूर्तिकर्ता का जमा खोलें और संशोधन माँगें।",
  "Click an issue to open the submission — request a revision there, and dispatch unlocks once the resubmission passes.": "किसी समस्या पर क्लिक करके जमा खोलें — वहाँ संशोधन माँगें, और पुनः जमा पास होते ही प्रेषण खुल जाता है।",
  "Comment to the supplier": "आपूर्तिकर्ता के लिए टिप्पणी",
  "Communication Template": "संचार टेम्पलेट",
  "Compliance email": "अनुपालन ईमेल",
  "Compliance intelligence": "अनुपालन बुद्धिमत्ता",
  "Copy Smart Link": "स्मार्ट लिंक कॉपी करें",
  "Cost & carbon": "लागत और कार्बन",
