  "Demo: records the confirmation that would arrive from their preview link.": "डेमो: वह पुष्टि दर्ज करता है जो उनके पूर्वावलोकन लिंक से आती।",
  "Difference": "अंतर",
  "dispatched": "भेजा गया",
