  "What buyers don't receive": "खरीदारों को क्या नहीं मिलता",
  "What changed": "क्या बदला",
  "What each good would be assumed to emit if nobody measured it. A figure below the fallback is the whole argument for collecting real data — and the number to put in front of a buyer.": "अगर कोई न मापे तो हर माल का कितना उत्सर्जन माना जाएगा। फ़ॉलबैक से नीचे का आँकड़ा असली डेटा जुटाने का पूरा तर्क है — और वही संख्या जो खरीदार के सामने रखी जाए।",
  "Why this looks different": "यह अलग क्यों दिखता है",
