  "months": "महीने",
  "Needs you": "आपकी ज़रूरत",
  "Nothing has happened yet.": "अभी कुछ नहीं हुआ।",
  "Supply chain": "आपूर्ति श्रृंखला",
  "What's new in CBAM?": "CBAM में नया क्या है?",
  "{fuel} — invoice": "{fuel} — चालान",
  "{month} is outside this reporting year.": "{month} इस रिपोर्टिंग वर्ष से बाहर है।",
  "{n} documents filed": "{n} दस्तावेज़ फ़ाइल किए गए",
  "Bills, invoices, meter logs, ERP exports, certificates — as many as you like. Certrace works out what each one is, which month it covers and where it belongs. Nothing is filed until you confirm.": "बिल, चालान, मीटर लॉग, ERP निर्यात, प्रमाणपत्र — जितने चाहें। Certrace पता लगाता है कि हर एक क्या है, किस महीने को कवर करता है और कहाँ जाता है। आपकी पुष्टि तक कुछ फ़ाइल नहीं होता।",
  "Could not file": "फ़ाइल नहीं हो सका",
  "Drop any documents here": "कोई भी दस्तावेज़ यहाँ डालें",
  "Drop your plant's documents here": "अपने प्लांट के दस्तावेज़ यहाँ डालें",
  "Filed to": "इसमें फ़ाइल किया गया",
  "Files to": "इसमें फ़ाइल होता है",
  "Month it covers": "जिस महीने को कवर करता है",
  "No specific month": "कोई विशिष्ट महीना नहीं",
  "Not needed — not filed.": "ज़रूरत नहीं — फ़ाइल नहीं हुआ।",
  "Open month": "महीना खोलें",
  "Pick a checklist row": "चेकलिस्ट की एक पंक्ति चुनें",
  "Pick a row above if it is needed anyway.": "अगर फिर भी चाहिए तो ऊपर की कोई पंक्ति चुनें।",
  "Set aside — not filed": "अलग रखा — फ़ाइल नहीं हुआ",
  "There is no {fuel} row in {month} yet. Filing adds one, with the EU standard factors.": "{month} में अभी {fuel} पंक्ति नहीं है। फ़ाइल करने पर EU मानक कारकों के साथ एक जुड़ती है।",
  "whole year": "पूरा साल",
  "Compare plans": "प्लान की तुलना करें",
  "{days}d left": "{days} दिन बचे",
  "Certrace — dashboard": "Certrace — डैशबोर्ड",
  "Dashboard": "डैशबोर्ड",
  "Days left in your trial. Everything is unlimited.": "आपके परीक्षण के बचे दिन। सब कुछ असीमित है।",
  "Earlier conversations with Cera": "Cera से पहले की बातचीत",
