  "Thai, English, Chinese and Hindi everywhere": "थाई, अंग्रेज़ी, चीनी और हिंदी हर जगह",
  "Days to get your figures to buyers": "खरीदारों को आँकड़े देने तक के दिन",
  "Your buyers file their first CBAM declaration on {date} and need your verified figures before then.": "आपके खरीदार {date} को पहली CBAM घोषणा दाखिल करते हैं और उससे पहले उन्हें आपके सत्यापित आँकड़े चाहिए।",
  "{name} submitted their data": "{name} ने अपना डेटा जमा किया",
  "{file} uploaded by {who}": "{file} {who} द्वारा अपलोड किया गया",
