  "Meter calibration certificate": "मीटर अंशांकन प्रमाणपत्र",
  "The plants that fill in your months — your own sites and your suppliers'": "वे प्लांट जो आपके महीने भरते हैं — आपकी अपनी साइटें और आपके आपूर्तिकर्ताओं की",
  "Search a name or a product": "नाम या उत्पाद खोजें",
  "No email on file to send the monthly link to": "मासिक लिंक भेजने के लिए कोई ईमेल दर्ज नहीं",
  "An email to send the monthly link to": "मासिक लिंक भेजने के लिए एक ईमेल",
  "Suppliers that fill in monthly, and what you buy in": "जो आपूर्तिकर्ता हर महीने भरते हैं, और जो आप खरीदते हैं",
  "Chat History": "चैट इतिहास",
  "{month} data is overdue": "{month} का डेटा देय तिथि पार कर चुका है",
  "{month} data is due soon": "{month} का डेटा जल्द देय है",
  "{product} · 1 day late": "{product} · 1 दिन देर",
  "{product} · {n} days late": "{product} · {n} दिन देर",
